/* ─── Today's Schedule (pickups + deliveries on a chosen date) ──── */
type ScheduleOrder = {
  id: string
  buyer_name: string | null
  buyer_phone: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  pickup_location: string | null
  delivery_type: 'self_pickup' | 'home_delivery' | null
  created_at: string
}

function TodayScheduleSection({ farmerId }: { farmerId: string }) {
  const { tx, L } = useLang()
  const todayStr = new Date().toLocaleDateString('en-CA') // YYYY-MM-DD, local
  const [date, setDate] = useState(todayStr)
  const [orders, setOrders] = useState<ScheduleOrder[]>([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    supabase
      .from('orders')
      .select('id, buyer_name, buyer_phone, produce_name, quantity, unit, pickup_location, delivery_type, created_at')
      .eq('farmer_id', farmerId)
      .eq('status', 'approved')
      .eq('fulfillment_date', date)
      .order('created_at', { ascending: true })
      .then(({ data }) => {
        if (cancelled) return
        setOrders((data ?? []) as ScheduleOrder[])
        setLoading(false)
      })
    return () => { cancelled = true }
  }, [farmerId, date])

  const pickups = orders.filter((o) => o.delivery_type !== 'home_delivery')
  const deliveries = orders.filter((o) => o.delivery_type === 'home_delivery')

  const Row = ({ o }: { o: ScheduleOrder }) => (
    <div className="border border-gray-100 rounded-xl px-3 py-2.5 bg-gray-50">
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="text-sm font-bold text-gray-900 truncate">{o.produce_name} · {o.quantity} {o.unit || 'kg'}</p>
          <p className="text-xs text-gray-600 truncate">🧑 {o.buyer_name || L('Buyer', 'కొనుగోలుదారు')}</p>
          {o.pickup_location && <p className="text-[11px] text-gray-500 truncate">📍 {o.pickup_location}</p>}
        </div>
        {o.buyer_phone && (
          <a href={`tel:+91${o.buyer_phone}`} className="text-[11px] font-bold text-green-700 bg-green-50 border border-green-200 rounded-lg px-2.5 py-1.5 whitespace-nowrap">
            📞 {o.buyer_phone}
          </a>
        )}
      </div>
    </div>
  )

  return (
    <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden">
      <div className="px-4 pt-4 pb-3 flex items-center justify-between border-b border-gray-100 gap-2">
        <h2 className="font-extrabold text-gray-900 text-base leading-tight">
          📅 {L("Today's Schedule", 'నేటి షెడ్యూల్')}
        </h2>
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value || todayStr)}
          className="border border-gray-200 rounded-lg px-2 py-1.5 text-xs bg-white focus:border-green-500 focus:outline-none"
        />
      </div>

      <div className="p-4 space-y-4">
        {loading ? (
          <p className="text-sm text-gray-400 text-center py-4">{tx.loadingLabel}</p>
        ) : orders.length === 0 ? (
          <p className="text-sm text-gray-400 text-center py-4">{L('Nothing scheduled for this date', 'ఈ తేదీకి ఏమీ లేదు')}</p>
        ) : (
          <>
            <div>
              <p className="text-xs font-bold text-green-800 uppercase tracking-wide mb-2">
                🧺 {L('Pickups', 'పికప్‌లు')} ({pickups.length})
              </p>
              {pickups.length === 0 ? (
                <p className="text-xs text-gray-400">{L('No pickups', 'పికప్‌లు లేవు')}</p>
              ) : (
                <div className="space-y-2">{pickups.map((o) => <Row key={o.id} o={o} />)}</div>
              )}
            </div>
            <div>
              <p className="text-xs font-bold text-blue-800 uppercase tracking-wide mb-2">
                🛵 {L('Deliveries', 'డెలివరీలు')} ({deliveries.length})
              </p>
              {deliveries.length === 0 ? (
                <p className="text-xs text-gray-400">{L('No deliveries', 'డెలివరీలు లేవు')}</p>
              ) : (
                <div className="space-y-2">{deliveries.map((o) => <Row key={o.id} o={o} />)}</div>
              )}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

function ListingRowCard({
  row,
  deleting,
  onDelete,
  onEdit,
  onTogglePause,
  onToggleSuspend,
}: {
  row: ListingRow
  deleting: boolean
  onDelete: () => void
  onEdit: () => void
  onTogglePause: () => void
  onToggleSuspend: () => void
}) {
  const { tx, L } = useLang()
  const emoji = row.emoji ?? '🌿'
  const isPaused = row.status === 'paused'
  const isSuspended = row.status === 'suspended_by_farmer'
  const statusLabel =
    row.status === 'available'
      ? tx.availableLabel
      : row.status === 'coming_soon'
      ? tx.comingSoon
      : row.status === 'paused'
      ? L('Paused by farmer', 'రైతు నిలిపివేశారు')
      : row.status === 'suspended_by_farmer'
      ? L('Suspended by you', 'మీరు నిలిపివేశారు')
      : row.status === 'suspended'
      ? L('Suspended', 'నిలిపివేయబడింది')
      : row.status === 'sold_out'
      ? L('Sold out', 'అయిపోయింది')
      : row.status
  const statusColor =
    row.status === 'available'
      ? 'bg-green-100 text-green-800'
      : row.status === 'coming_soon'
      ? 'bg-amber-100 text-amber-800'
      : row.status === 'paused'
      ? 'bg-purple-100 text-purple-800'
      : row.status === 'suspended_by_farmer'
      ? 'bg-red-100 text-red-800'
      : row.status === 'suspended'
      ? 'bg-orange-100 text-orange-800'
      : 'bg-gray-100 text-gray-700'
  // Farmer can pause/resume their own active or sold-out listings (not
  // moderator-suspended or coming-soon ones). Pause and Suspend are mutually
  // exclusive states, so each control hides while the other is active.
  const canPause = row.status === 'available' || row.status === 'sold_out' || row.status === 'paused'
  const canSuspend = row.status === 'available' || row.status === 'sold_out' || row.status === 'suspended_by_farmer'

  return (
    <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
      <div className="flex gap-3 p-3">
        {row.image_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={row.image_url}
            alt={row.name}
            loading="lazy"
            className="rounded-xl w-16 h-16 object-cover flex-shrink-0 bg-gray-100"
          />
        ) : (
          <div className="bg-green-50 rounded-xl w-16 h-16 flex items-center justify-center text-3xl flex-shrink-0">
            {emoji}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <h4 className="font-bold text-gray-900 text-sm truncate">{row.name}</h4>
              {row.variety && <p className="text-xs text-gray-500 truncate">{row.variety}</p>}
            </div>
            <span className={`${statusColor} text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap`}>
              {statusLabel}
            </span>
          </div>
          <div className="flex items-center gap-3 mt-2 text-xs text-gray-600 flex-wrap">
            {row.price_tier_1_price != null && (
              <span className="font-bold text-green-700 text-sm">
                ₹{row.price_tier_1_price}
                <span className="text-gray-400 font-normal text-xs">/{row.unit || 'kg'}</span>
              </span>
            )}
            {row.stock_qty != null && (
              <span className="font-semibold text-gray-700">{row.stock_qty} {row.unit || tx.kgLabel}</span>
            )}
            {row.method && (
              <span className="bg-green-50 text-green-800 text-[10px] font-semibold px-2 py-0.5 rounded-full">
                {row.method}
              </span>
            )}
            {row.harvest_date && (
              <FreshnessBadge harvestDate={row.harvest_date} />
            )}
          </div>
        </div>
      </div>

      <div className="px-3 pb-3 space-y-2">
        {/* Pause / Suspend — two independent reversible hide-from-buyers
            controls, both distinct from Delete. Only the relevant one shows
            once a listing is already paused or suspended. */}
        {(canPause || canSuspend) && (
          <div className="flex gap-2">
            {canPause && (
              <button
                onClick={onTogglePause}
                className={`flex-1 font-bold py-2.5 rounded-xl text-sm border ${
                  isPaused
                    ? 'border-green-600 text-green-700 active:bg-green-50'
                    : 'border-purple-300 text-purple-700 active:bg-purple-50'
                }`}
              >
                {isPaused ? L('▶ Resume', 'తిరిగి చూపించు') : L('⏸ Pause', 'అమ్మకం ఆపండి')}
              </button>
            )}
            {canSuspend && (
              <button
                onClick={onToggleSuspend}
                className={`flex-1 font-bold py-2.5 rounded-xl text-sm border ${
                  isSuspended
                    ? 'border-green-600 text-green-700 active:bg-green-50'
                    : 'border-red-300 text-red-600 active:bg-red-50'
                }`}
              >
                {isSuspended ? L('▶ Resume', 'తిరిగి చూపించు') : L('⛔ Suspend', 'నిలిపివేయి')}
              </button>
            )}
          </div>
        )}
        <div className="flex gap-2">
          <button
            onClick={onEdit}
            className="flex-1 border border-blue-200 text-blue-700 font-bold py-2.5 rounded-xl text-sm active:bg-blue-50"
          >
            ✏️ {tx.editListing}
          </button>
          <button
            onClick={onDelete}
            disabled={deleting}
            className="flex-1 border border-red-200 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
          >
            {deleting ? tx.deleting : `🗑 ${tx.deleteProduce}`}
          </button>
        </div>
      </div>
    </div>
  )
}

/* ─── Order card ─────────────────────────────────────────────── */
function OrderCard({
  order,
  processing,
  processingPaid,
  onApprove,
  onDecline,
  onMarkPaid,
  onUpdatePaymentStatus,
  onSetFulfillmentDate,
  onMarkPickedUp,
  onMarkShipped,
}: {

'use client'

import { useEffect, useState, useCallback } from 'react'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import LanguageToggle from '@/components/LanguageToggle'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ComplaintModal from '@/components/consumer/ComplaintModal'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

type Order = {
  id: string
  order_code: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method: string | null
  payment_status: string | null
  refund_status: string | null
  decline_reason: string | null
  payment_proof_path: string | null
  created_at: string
  farmer_id: string
  farmer?: {
    name: string
    slug: string
    village: string
    phone: string | null
    upi_id: string | null
  } | null
  delivery_type?: 'self_pickup' | 'home_delivery' | null
  delivery_status?: DeliveryStatus | null
}

export default function ConsumerOrdersPage() {
  const { tx, lang, L } = useLang()
  const { state, openAuth } = useConsumerAuth()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [retryingId, setRetryingId] = useState<string | null>(null)
  // Order code the complaint modal is pinned to ('' means a general complaint
  // with no preset). null means the modal is closed.
  const [complaintFor, setComplaintFor] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    setLoading(true)
    setError('')
    const r = await fetch('/api/consumer/orders', { credentials: 'same-origin' }).catch(() => null)
    if (!r) { setError('Could not load orders. Check your connection.'); setLoading(false); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load orders.'); setLoading(false); return }
    setOrders((json.orders ?? []) as Order[])
    setLoading(false)
  }, [])

  useEffect(() => {
    if (state.status === 'authenticated') {
      void refresh()
    } else if (state.status === 'anonymous') {
      setLoading(false)
    }
  }, [state.status, refresh])

  const handleRetryPayment = async (order: Order) => {
    if (order.status === 'declined') return
    setRetryingId(order.id)
    const r = await fetch(`/api/orders/${order.id}/retry`, {
      method: 'POST',
      credentials: 'same-origin',
    }).catch(() => null)
    setRetryingId(null)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not retry payment.'); return }

    setOrders((prev) => prev.map((o) =>
      o.id === order.id ? { ...o, payment_status: 'pending', payment_proof_path: null } : o,
    ))
    if (order.farmer?.upi_id && order.total_price) {
      const upiLink = `upi://pay?pa=${encodeURIComponent(order.farmer.upi_id)}&pn=${encodeURIComponent(order.farmer.name)}&am=${order.total_price}&cu=INR&tn=YourFamilyFarmer%20Order`
      window.location.href = upiLink
    }
  }

  const statusColor = (s: string) =>
    s === 'approved'
      ? 'bg-green-100 text-green-800'
      : s === 'declined'
        ? 'bg-red-100 text-red-700'
        : s === 'cancelled'
          ? 'bg-gray-200 text-gray-700'
          : 'bg-amber-100 text-amber-800'

  const deliveryStatusLabel = (s: DeliveryStatus | null | undefined) => {
    switch (s) {
      case 'assigned': return L('Rider assigned', 'రైడర్ కేటాయించబడ్డారు')
      case 'picked_up': return L('Picked up', 'తీసుకున్నారు')
      case 'out_for_delivery': return L('Out for delivery', 'డెలివరీకి బయలుదేరారు')
      case 'delivered': return L('Delivered', 'డెలివరీ అయింది')
      default: return L('Waiting for rider', 'రైడర్ కోసం వేచి ఉంది')
    }
  }

  const statusLabel = (s: string) =>
    s === 'approved' ? tx.statusConfirmed
      : s === 'declined' ? tx.statusDeclined
      : s === 'cancelled' ? tx.statusCancelled
      : tx.statusPending

  const paymentBadge = (order: Order) => {
    if (!order.payment_method || order.payment_method === 'cod') return null
    // Online payments now go through Razorpay.
    if (order.payment_method === 'razorpay' && order.payment_status === 'paid') {
      return { label: L('✓ Paid online', 'ఆన్‌లైన్ చెల్లించారు'), cls: 'bg-green-100 text-green-800' }
    }
    // Manual UPI is retired — legacy UPI orders show no pay prompt.
    return null
  }

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer" className="text-green-300 text-sm flex items-center gap-1">
            {L('← Back', '← వెనక్కు')}
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">{tx.myOrders}</h1>
        <p className="text-green-400 text-sm mt-1">
          {L('Your complete order history', 'మీ ఆర్డర్ల చరిత్ర')}
        </p>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {state.status === 'loading' || loading ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
            {L('Loading...', 'లోడ్ అవుతోంది')}
          </div>
        ) : state.status === 'anonymous' ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
            <div className="text-5xl">🔒</div>
            <div>
              <p className="font-bold text-gray-900">
                {L('Log in to see your orders', 'మీ ఆర్డర్‌లు చూడటానికి లాగిన్ అవ్వండి')}
              </p>
            </div>
            <button
              onClick={openAuth}
              className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
            >
              {L('Log in', 'లాగిన్')}
            </button>
          </div>
        ) : error ? (
          <div className="bg-white rounded-2xl border border-red-100 p-6 space-y-3">
            <p className="text-sm text-red-600">{error}</p>
            <button
              onClick={() => void refresh()}
              className="text-sm font-bold text-green-700 underline"
            >
              {L('Try again', 'మళ్లీ ప్రయత్నించండి')}
            </button>
          </div>
        ) : orders.length === 0 ? (
          <div className="text-center py-14">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noOrdersYet}</p>
            <Link href="/consumer" className="mt-4 inline-block text-green-700 text-sm underline font-semibold">
              {L('Browse produce →', 'పంట చూడండి →')}
            </Link>
          </div>
        ) : (
          <div className="space-y-3">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
              {orders.length} {L(`order${orders.length !== 1 ? 's' : ''} found`, 'ఆర్డర్‌లు దొరికాయి')}
            </p>
            {orders.map((order) => {
              const badge = paymentBadge(order)
              // Manual UPI flow retired — no pay-via-UPI prompt or retry on legacy orders.
              const needsPayment = false
              const canRetry = false
              const upiLink: string | null = null
              return (
                <Link key={order.id} href={`/consumer/orders/${order.id}`} className="block">
                  <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden active:bg-gray-50">
                    <div className="p-4 space-y-2">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <p className="font-extrabold text-gray-900 text-sm leading-tight">
                            {localizeName(order.produce_name, lang) || '—'}
                          </p>
                          {order.order_code && (
                            <p className="text-[11px] font-mono font-semibold text-gray-400 mt-0.5">
                              {order.order_code}
                            </p>
                          )}
                          <p className="text-xs text-gray-500 mt-0.5">
                            {order.quantity} {order.unit || 'kg'}
                            {order.total_price ? ` · ₹${order.total_price}` : ''}
                          </p>
                        </div>
                        <div className="flex flex-col items-end gap-1 flex-shrink-0">
                          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                            {statusLabel(order.status)}
                          </span>
                          {badge && (
                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${badge.cls}`}>
                              {badge.label}
                            </span>
                          )}
                          {order.refund_status && order.refund_status !== 'failed' && (
                            <span className="text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap bg-purple-100 text-purple-800">
                              💸 {order.refund_status === 'processed' ? L('Refunded', 'రీఫండ్ అయింది') : L('Refund initiated', 'రీఫండ్ ప్రారంభమైంది')}
                            </span>
                          )}
                          {order.refund_status === 'failed' && (
                            <span className="text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap bg-red-100 text-red-800">
                              {L('⚠️ Refund failed', '⚠️ రీఫండ్ విఫలమైంది')}
                            </span>
                          )}
                        </div>
                      </div>

                      {order.farmer && (
                        <p className="flex items-center gap-1.5 text-xs text-green-700 font-semibold">
                          🧑‍🌾 {tx.orderedFrom} {order.farmer.name} · {order.farmer.village}
                        </p>
                      )}

                      {order.delivery_type === 'home_delivery' ? (
                        <p className="text-xs text-blue-700 font-semibold">
                          🛵 {L('Home delivery', 'హోమ్ డెలివరీ')} · {deliveryStatusLabel(order.delivery_status)}
                        </p>
                      ) : order.pickup_location ? (
                        <p className="text-xs text-gray-500">📍 {tx.pickedUpAt}: {order.pickup_location}</p>
                      ) : null}

                      <p className="text-[11px] text-gray-400">
                        {new Date(order.created_at).toLocaleDateString('en-IN', {
                          day: 'numeric',
                          month: 'short',
                          year: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </p>

                      {/* Decline reason — shown only when farmer declined */}
                      {order.status === 'declined' && order.decline_reason && (
                        <div className="bg-red-50 border border-red-200 rounded-xl px-3 py-2 mt-1">
                          <p className="text-[10px] font-bold text-red-700 uppercase tracking-wide">
                            {L('Reason', 'కారణం')}
                          </p>
                          <p className="text-xs text-red-800 mt-0.5 leading-snug">{order.decline_reason}</p>
                        </div>
                      )}

                      {/* Refund message — shown when a paid order was declined */}
                      {order.status === 'declined' && order.refund_status === 'initiated' && (
                        <div className="bg-purple-50 border border-purple-200 rounded-xl px-3 py-2 mt-1">
                          <p className="text-xs text-purple-800 leading-snug">
                            {L(
                              `Your payment of Rs.${order.total_price ?? 0} will be refunded to your account in 3-5 business days`,
                              `మీ చెల్లింపు Rs.${order.total_price ?? 0} 3-5 పని దినాలలో తిరిగి వస్తుంది`,
                            )}
                          </p>
                        </div>
                      )}

                      {/* Pay Now button for pending UPI orders */}
                      {needsPayment && upiLink && (
                        <div className="pt-1 space-y-2">
                          <button
                            type="button"
                            onClick={(e) => { e.preventDefault(); window.location.href = upiLink }}
                            className="w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm active:bg-green-800"
                          >
                            📲 Pay ₹{order.total_price} via UPI
                          </button>
                          <p className="text-[11px] text-gray-500 text-center">
                            UPI ID: <span className="font-mono font-semibold">{order.farmer?.upi_id}</span>
                          </p>
                        </div>
                      )}

                      {/* Retry payment */}
                      {canRetry && (
                        <div className="pt-1 space-y-2">
                          <div className="bg-amber-50 border border-amber-200 rounded-xl px-3 py-2">
                            <p className="text-xs font-bold text-amber-800">
                              {L('Farmer did not receive your payment', 'రైతుకు చెల్లింపు అందలేదు')}
                            </p>
                            <p className="text-[11px] text-amber-700 mt-0.5">
                              Tap retry to pay again. The farmer will be re-notified.
                            </p>
                          </div>
                          <button
                            type="button"
                            onClick={(e) => { e.preventDefault(); void handleRetryPayment(order) }}
                            disabled={retryingId === order.id}
                            className="w-full bg-amber-600 text-white font-bold py-3 rounded-xl text-sm active:bg-amber-700 disabled:opacity-50"
                          >
                            {retryingId === order.id ? 'Opening UPI...' : `🔄 Retry payment ₹${order.total_price}`}
                          </button>
                        </div>
                      )}

                      {/* Per-order complaint — opens the shared modal pinned to
                          this order's code so the buyer needn't type it. */}
                      <div className="pt-1">
                        <button
                          type="button"
                          onClick={(e) => {
                            e.preventDefault()
                            e.stopPropagation()
                            setComplaintFor(order.order_code ?? '')
                          }}
                          className="w-full text-center text-xs font-bold text-amber-700 bg-amber-50 border border-amber-200 rounded-xl py-2.5 active:bg-amber-100"
                        >
                          🛟 {L('Log a Complaint', 'ఫిర్యాదు')}
                        </button>
                      </div>
                    </div>
                  </div>
                </Link>
              )
            })}
          </div>
        )}

        <Link
          href="/consumer/complaints"
          className="mt-6 block text-center text-xs font-semibold text-green-700 underline"
        >
          🛟 {L('My complaints', 'నా ఫిర్యాదులు')}
        </Link>

        <Link
          href="/buyer-protection"
          className="mt-3 block text-center text-xs font-semibold text-green-700 underline"
        >
          🔒 {L('Buyer protection & refund policy', 'కొనుగోలుదారు రక్షణ & రీఫండ్ విధానం')}
        </Link>
      </div>

      {complaintFor !== null && (
        <ComplaintModal
          presetOrderCode={complaintFor || null}
          onClose={() => setComplaintFor(null)}
          onCreated={() => setComplaintFor(null)}
        />
      )}
    </main>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import LanguageToggle from '@/components/LanguageToggle'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ComplaintModal from '@/components/consumer/ComplaintModal'
import ProduceReviewBox, { type MyReview } from '@/components/consumer/ProduceReviewBox'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

// Fire a browser notification for a buyer-facing status change (e.g. the farmer
// shipped the parcel). Permission-gated: silently no-ops unless the buyer has
// granted notifications, so it's safe to call unconditionally.
function fireConsumerNotification(title: string, body: string) {
  if (typeof window === 'undefined' || !('Notification' in window)) return
  if (Notification.permission !== 'granted') return
  try {
    new Notification(title, { body, icon: '/icon-192.png', tag: 'yff-order-status' })
  } catch { /* some browsers throw on background tabs — ignore */ }
}

type Order = {
  id: string
  order_code: string | null
  produce_name: string | null
  produce_listing_id?: string | null
  my_review?: MyReview | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method: string | null
  payment_method_detail?: string | null
  payment_status: string | null
  paid_at?: string | null
  confirmed_at?: string | null
  razorpay_payment_id: string | null
  refund_status: string | null
  refund_id: string | null
  refund_amount: number | null
  refunded_at: string | null
  decline_reason: string | null
  payment_proof_path: string | null
  created_at: string
  farmer_id: string
  farmer?: {
    name: string
    slug: string
    village: string
    phone: string | null
    upi_id: string | null
  } | null
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  delivery_address?: string | null
  delivery_landmark?: string | null
  delivery_pincode?: string | null
  delivery_alt_phone?: string | null
  handover_otp?: string | null
  assigned_at?: string | null
  picked_up_at?: string | null
  out_for_delivery_at?: string | null
  delivered_at?: string | null
  collected_at?: string | null
  shipped_at?: string | null
  received_at?: string | null
  fulfillment_date?: string | null
  rider?: { id: string; name: string | null; phone: string } | null
}

// Online payments go through Razorpay (stored as payment_method 'razorpay';
// some legacy orders use 'upi'). The real instrument the buyer used — PhonePe /
// Google Pay / UPI / Card — is resolved into payment_method_detail after the
// payment is verified. Never surface the gateway name "razorpay" to the buyer.
function isOnlinePayment(method: string | null | undefined): boolean {
  return method === 'razorpay' || method === 'upi'
}

export default function OrderDetailsPage() {
  const params = useParams<{ id: string }>()
  const id = typeof params?.id === 'string' ? params.id : ''
  const { state, openAuth } = useConsumerAuth()
  const { tx, L, lang } = useLang()
  const [order, setOrder] = useState<Order | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [proofUrl, setProofUrl] = useState<string | null>(null)
  const [proofLoading, setProofLoading] = useState(false)
  const [showReceipt, setShowReceipt] = useState(false)
  const [cancelling, setCancelling] = useState(false)
  const [showComplaint, setShowComplaint] = useState(false)
  const [confirmingReceipt, setConfirmingReceipt] = useState(false)

  // Buyer may cancel only while still pending and within 30 min of placing.
  const canCancel = !!order
    && order.status === 'pending'
    && !!order.created_at
    && Date.now() - new Date(order.created_at).getTime() < 30 * 60 * 1000

  // A shipped courier order awaits the buyer's "Received" confirmation.
  const canConfirmReceipt = !!order
    && order.delivery_type === 'courier'
    && !!order.shipped_at
    && !order.received_at

  const handleCancel = async () => {
    if (!order) return
    if (!window.confirm(L('Cancel this order? If you have already paid, you will be refunded automatically.', 'ఈ ఆర్డర్‌ను రద్దు చేయాలా? మీరు ఇప్పటికే చెల్లించి ఉంటే, డబ్బు ఆటోమేటిక్‌గా తిరిగి వస్తుంది.'))) return
    setCancelling(true)
    try {
      const res = await fetch(`/api/consumer/orders/${order.id}/cancel`, {
        method: 'POST',
        credentials: 'same-origin',
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) { alert(json.error || L('Could not cancel the order.', 'ఆర్డర్ రద్దు చేయలేకపోయాం.')); return }
      // Refresh the order so status + any refund show up.
      const r = await fetch(`/api/consumer/orders/${order.id}`, { credentials: 'same-origin' })
      const fresh = await r.json().catch(() => ({}))
      if (r.ok && fresh.order) setOrder(fresh.order as Order)
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setCancelling(false)
    }
  }

  const handleConfirmReceipt = async () => {
    if (!order) return
    if (!window.confirm(L('Confirm you received this order?', 'మీరు ఈ ఆర్డర్‌ను అందుకున్నారా?'))) return
    setConfirmingReceipt(true)
    try {
      const res = await fetch(`/api/consumer/orders/${order.id}/received`, {
        method: 'POST',
        credentials: 'same-origin',
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) { alert(json.error || L('Could not confirm receipt.', 'అందుకున్నట్టు ధృవీకరించలేకపోయాం.')); return }
      const r = await fetch(`/api/consumer/orders/${order.id}`, { credentials: 'same-origin' })
      const fresh = await r.json().catch(() => ({}))
      if (r.ok && fresh.order) setOrder(fresh.order as Order)
    } catch {
      alert(L('Network error. Please try again.', 'నెట్‌వర్క్ సమస్య. మళ్ళీ ప్రయత్నించండి.'))
    } finally {
      setConfirmingReceipt(false)
    }
  }

  useEffect(() => {
    if (state.status !== 'authenticated' || !id) {
      if (state.status === 'anonymous') setLoading(false)
      return
    }
    let cancelled = false
    setLoading(true)
    setError('')
    fetch(`/api/consumer/orders/${id}`, { credentials: 'same-origin' })
      .then(async (r) => {
        const json = await r.json().catch(() => ({}))
        if (cancelled) return
        if (!r.ok) {
          setError(json?.error ?? 'Could not load order.')
          setLoading(false)
          return
        }
        setOrder(json.order as Order)
        setLoading(false)
      })
      .catch(() => {
        if (cancelled) return
        setError('Network error. Please try again.')
        setLoading(false)
      })
    return () => { cancelled = true }
  }, [id, state.status])

  // Light polling so status changes the farmer/rider make (e.g. Shipped) show up
  // here without a manual refresh. Stops once the order reaches a final state.
  const orderDone = !!order && (
    order.status === 'declined'
    || order.status === 'cancelled'
    || !!order.received_at
    || !!order.collected_at
    || order.delivery_status === 'delivered'
  )
  const orderActive = !!order && !orderDone && (order.status === 'pending' || order.status === 'approved')
  useEffect(() => {
    if (!orderActive || !id || state.status !== 'authenticated') return
    const timer = setInterval(() => {
      fetch(`/api/consumer/orders/${id}`, { credentials: 'same-origin' })
        .then(async (r) => {
          if (!r.ok) return
          const json = await r.json().catch(() => ({}))
          if (!json.order) return
          const next = json.order as Order
          // Notify the buyer the moment a status they're waiting on flips.
          setOrder((prev) => {
            if (prev && !prev.shipped_at && next.shipped_at) {
              fireConsumerNotification(
                L('Your order has shipped 📦', 'ఆర్డర్ షిప్ చేయబడింది'),
                L(`${next.produce_name ?? 'Your order'} is on the way. Tap "Received" once it arrives.`, `మీ ఆర్డర్ వస్తోంది. వచ్చాక "అందుకున్నాను" నొక్కండి.`),
              )
            }
            return next
          })
        })
        .catch(() => {})
    }, 25000)
    return () => clearInterval(timer)
  }, [orderActive, id, state.status])

  // Resolve a fresh signed URL for the payment screenshot
  useEffect(() => {
    if (!order?.payment_proof_path) { setProofUrl(null); return }
    let cancelled = false
    setProofLoading(true)
    fetch(`/api/orders/${order.id}/proof`, { credentials: 'same-origin' })
      .then(async (r) => {
        const json = await r.json().catch(() => ({}))
        if (cancelled) return
        setProofUrl(typeof json?.url === 'string' ? json.url : null)
        setProofLoading(false)
      })
      .catch(() => { if (!cancelled) setProofLoading(false) })
    return () => { cancelled = true }
  }, [order?.id, order?.payment_proof_path])

  const statusColor = (s: string) =>
    s === 'approved' ? 'bg-green-100 text-green-800'
      : s === 'declined' ? 'bg-red-100 text-red-700'
      : s === 'cancelled' ? 'bg-gray-200 text-gray-700'
      : 'bg-amber-100 text-amber-800'

  const statusLabel = (s: string) =>
    s === 'approved' ? tx.statusConfirmed
      : s === 'declined' ? tx.statusDeclined
      : s === 'cancelled' ? tx.statusCancelled
      : tx.statusPending

  const paymentLabel = (o: Order) => {
    if (o.payment_method === 'cod') return L('Cash on Delivery', 'నగదు చెల్లింపు')
    if (isOnlinePayment(o.payment_method)) {
      // Show the real method (PhonePe / Google Pay / UPI…) once we know it,
      // instead of the gateway name. Falls back to "UPI" before it resolves.
      const m = o.payment_method_detail || 'UPI'
      if (o.payment_status === 'paid' || o.payment_status === 'completed') return `${m} ✓ Paid`
      if (o.payment_status === 'pending_confirmation' || o.payment_status === 'payment_claimed')
        return `${m} ⏳ Awaiting farmer confirmation`
      if (o.payment_status === 'failed') return `${m} ✕ Not received`
      return `${m} · Pending`
    }
    return o.payment_method ?? '—'
  }

  const orderDate = order
    ? new Date(order.created_at).toLocaleDateString('en-IN', {
        day: 'numeric', month: 'short', year: 'numeric',
      })
    : ''
  const orderTime = order
    ? new Date(order.created_at).toLocaleTimeString('en-IN', {
        hour: '2-digit', minute: '2-digit',
      })
    : ''

  const whatsappHref = order?.farmer?.phone && order?.produce_name
    ? `https://wa.me/91${order.farmer.phone.replace(/\D/g, '').slice(-10)}?text=${encodeURIComponent(
        `Hello ${order.farmer.name} anna, regarding my order of ${order.produce_name} on ${orderDate}.`,
      )}`
    : null

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <div className="flex items-center justify-between mb-4">
          <Link href="/consumer/orders" className="text-green-300 text-sm flex items-center gap-1">
            ← {L('Back', 'వెనక్కు')}
          </Link>
          <LanguageToggle />
        </div>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {L('Order details', 'ఆర్డర్ వివరాలు')}
        </h1>
      </div>

      <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
        {state.status === 'anonymous' ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
            <div className="text-5xl">🔒</div>
            <p className="font-bold text-gray-900">Log in to view this order</p>
            <button
              onClick={openAuth}
              className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
            >
              {L('Log in', 'లాగిన్')}
            </button>
          </div>
        ) : loading ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
            {L('Loading...', 'లోడ్ అవుతోంది')}
          </div>
        ) : error ? (
          <div className="bg-white rounded-2xl border border-red-100 p-6 text-sm text-red-600">{error}</div>
        ) : !order ? null : (
          <>
            {/* Status + payment summary */}
            <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Order</p>
                  {order.order_code && (
                    <p className="text-[11px] font-mono font-semibold text-gray-400">{order.order_code}</p>
                  )}
                  <p className="text-base font-extrabold text-gray-900 leading-tight">
                    {localizeName(order.produce_name, lang) || '—'}
                  </p>
                  <p className="text-xs text-gray-500 mt-0.5">
                    {order.quantity} {order.unit || 'kg'}
                    {order.total_price ? ` · ₹${order.total_price}` : ''}
                  </p>
                </div>
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                  {statusLabel(order.status)}
                </span>
              </div>

              <div className="grid grid-cols-2 gap-3 pt-1 border-t border-gray-100 mt-3">
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Placed</p>
                  <p className="text-xs font-semibold text-gray-700">{orderDate}</p>
                  <p className="text-[11px] text-gray-500">{orderTime}</p>
                </div>
                <div>
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Payment</p>
                  <p className="text-xs font-semibold text-gray-700">{paymentLabel(order)}</p>
                </div>
              </div>

              {order.pickup_location && (
                <div className="pt-1 border-t border-gray-100 mt-1">
                  <p className="text-[10px] font-bold text-gray-400 uppercase">Pickup</p>
                  <p className="text-xs font-semibold text-gray-700">📍 {order.pickup_location}</p>
                </div>
              )}

              {(order.payment_status === 'paid' || order.payment_status === 'completed') && (
                <button
                  onClick={() => setShowReceipt(true)}
                  className="mt-3 w-full border border-green-600 text-green-700 font-bold py-2.5 rounded-xl text-sm active:bg-green-50"
                >
                  🧾 {L('View receipt', 'రసీదు చూడండి')}
                </button>
              )}

              {canCancel && (
                <button
                  onClick={handleCancel}
                  disabled={cancelling}
                  className="mt-2 w-full border border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
                >
                  {cancelling ? L('Cancelling...', 'రద్దు చేస్తోంది...') : L('✕ Cancel order', 'ఆర్డర్ రద్దు (30 min లోపు)')}
                </button>
              )}

              {canConfirmReceipt && (
                <button
                  onClick={handleConfirmReceipt}
                  disabled={confirmingReceipt}
                  className="mt-3 w-full bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700 disabled:opacity-50"
                >
                  {confirmingReceipt ? '…' : L('✓ Received', 'అందుకున్నాను')}
                </button>
              )}
            </div>

            {/* Pickup / Delivery date the farmer scheduled for this order. */}
            {order.fulfillment_date && order.status !== 'declined' && order.status !== 'cancelled' && (
              <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center gap-3">
                <span className="text-2xl">📅</span>
                <div>
                  <p className="text-[10px] font-bold text-green-700 uppercase tracking-wide">
                    {order.delivery_type === 'home_delivery'
                      ? L('Delivery date', 'డెలివరీ తేదీ')
                      : L('Pickup date', 'పికప్ తేదీ')}
                  </p>
                  <p className="text-sm font-extrabold text-green-900 mt-0.5">
                    {new Date(`${order.fulfillment_date}T00:00:00`).toLocaleDateString('en-IN', {
                      weekday: 'short', day: 'numeric', month: 'short', year: 'numeric',
                    })}
                  </p>
                </div>
              </div>
            )}

            {/* Delivery timeline + handover OTP — only for home delivery orders */}
            {order.delivery_type === 'home_delivery' && order.status !== 'declined' && (
              <DeliveryPanel order={order} />
            )}

            {/* Simple status timeline for self-pickup orders */}
            {order.delivery_type !== 'home_delivery' && order.status !== 'declined' && (
              <OrderStatusPanel order={order} />
            )}

            {/* Rate the produce — only once the order is completed. */}
            {order.produce_listing_id
              && order.status !== 'declined'
              && order.status !== 'cancelled'
              && (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered') && (
              <ProduceReviewBox
                orderId={order.id}
                produceName={order.produce_name ? localizeName(order.produce_name, lang) : L('this produce', 'ఈ ఉత్పత్తి')}
                existing={order.my_review ?? null}
              />
            )}

            {/* Decline reason */}
            {order.status === 'declined' && order.decline_reason && (
              <div className="bg-red-50 border border-red-200 rounded-2xl p-4">
                <p className="text-xs font-bold text-red-700 uppercase tracking-wide">{L('Decline reason', 'కారణం')}</p>
                <p className="text-sm text-red-800 mt-1 leading-snug">{order.decline_reason}</p>
              </div>
            )}

            {/* Refund status — shown whenever a refund exists for this order */}
            {order.refund_status && <RefundPanel order={order} />}

            {/* Payment screenshot */}
            {order.payment_method === 'upi' && (
              <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-2">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
                  {L('Payment screenshot', 'చెల్లింపు స్క్రీన్‌షాట్')}
                </p>
                {!order.payment_proof_path ? (
                  <p className="text-xs text-gray-500">No screenshot uploaded yet.</p>
                ) : proofLoading ? (
                  <p className="text-xs text-gray-500">Loading...</p>
                ) : proofUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={proofUrl}
                    alt="Payment screenshot"
                    className="w-full max-h-96 object-contain rounded-xl border border-gray-200 bg-gray-50"
                  />
                ) : (
                  <p className="text-xs text-red-600">Could not load screenshot. Please refresh.</p>
                )}
              </div>
            )}

            {/* Farmer details */}
            {order.farmer && (
              <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
                <p className="text-xs font-bold text-gray-500 uppercase tracking-wide">
                  {L('Farmer', 'రైతు')}
                </p>
                <div>
                  <p className="text-base font-extrabold text-gray-900 leading-tight">🧑‍🌾 {order.farmer.name}</p>
                  <p className="text-xs text-gray-500 mt-0.5">📍 {order.farmer.village}</p>
                </div>
                <Link
                  href={`/farmer/${order.farmer.slug}`}
                  className="block text-center text-sm font-bold text-green-700 underline"
                >
                  {L('View farm profile', 'రైతు ప్రొఫైల్ చూడండి ↗')}
                </Link>
                {whatsappHref && (
                  <a
                    href={whatsappHref}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="w-full bg-green-600 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-700 flex items-center justify-center gap-2"
                  >
                    💬 {L('Contact Farmer', 'రైతును సంప్రదించు')}
                  </a>
                )}
              </div>
            )}

            {/* Report a problem — pins the complaint to this order automatically */}
            <button
              onClick={() => setShowComplaint(true)}
              className="w-full border border-gray-300 text-gray-700 font-bold py-3 rounded-xl text-sm active:bg-gray-50"
            >
              🛟 {L('Report a problem', 'సమస్యను నివేదించండి')}
            </button>
          </>
        )}
      </div>

      {showReceipt && order && (
        <ReceiptOverlay order={order} onClose={() => setShowReceipt(false)} />
      )}

      {showComplaint && order && (
        <ComplaintModal
          presetOrderCode={order.order_code}
          onClose={() => setShowComplaint(false)}
          onCreated={() => setShowComplaint(false)}
        />
      )}
    </main>
  )
}

// Printable payment receipt. Shown as an overlay; the print stylesheet hides
// everything except .yff-receipt so "Print / Save as PDF" produces a clean
// one-page receipt on both phones and laptops.
function ReceiptOverlay({ order, onClose }: { order: Order; onClose: () => void }) {
  const { lang, L } = useLang()
  const placed = new Date(order.created_at).toLocaleString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit',
  })
  const paymentRef = order.razorpay_payment_id || order.order_code || order.id

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4 overflow-y-auto">
      <style>{`@media print {
        body * { visibility: hidden !important; }
        .yff-receipt, .yff-receipt * { visibility: visible !important; }
        .yff-receipt { position: absolute; left: 0; top: 0; width: 100%; box-shadow: none !important; }
        .yff-no-print { display: none !important; }
      }`}</style>

      <div className="yff-receipt bg-white rounded-2xl w-full max-w-sm p-6 my-auto">
        <div className="text-center border-b border-dashed border-gray-300 pb-3">
          <p className="text-lg font-extrabold text-green-700">YourFamilyFarmer</p>
          <p className="text-[11px] text-gray-500">{L('Payment Receipt', 'చెల్లింపు రసీదు')}</p>
        </div>

        <div className="py-3 space-y-1.5 text-xs">
          <div className="flex justify-between"><span className="text-gray-500">{L('Order ID', 'ఆర్డర్ ID')}</span><span className="font-mono font-bold text-gray-900">{order.order_code || order.id.slice(0, 8)}</span></div>
          <div className="flex justify-between"><span className="text-gray-500">{L('Date', 'తేదీ')}</span><span className="font-semibold text-gray-900">{placed}</span></div>
          {order.farmer && (
            <div className="flex justify-between"><span className="text-gray-500">{L('Farmer', 'రైతు')}</span><span className="font-semibold text-gray-900 text-right">{order.farmer.name} · {order.farmer.village}</span></div>
          )}
          <div className="flex justify-between"><span className="text-gray-500">{L('Payment', 'చెల్లింపు')}</span><span className="font-semibold text-gray-900">{order.payment_method_detail || (order.payment_method === 'cod' ? 'Cash on Delivery' : isOnlinePayment(order.payment_method) ? 'UPI' : order.payment_method || '—')}</span></div>
        </div>

        <div className="border-t border-dashed border-gray-300 py-3">
          <div className="flex justify-between text-xs">
            <span className="text-gray-700">{localizeName(order.produce_name, lang)} × {order.quantity} {order.unit || 'kg'}</span>
            <span className="font-semibold text-gray-900">₹{order.total_price ?? 0}</span>
          </div>
        </div>

        <div className="border-t-2 border-gray-900 pt-2 flex justify-between items-center">
          <span className="text-sm font-bold text-gray-900">{L('Total Paid', 'మొత్తం చెల్లించారు')}</span>
          <span className="text-lg font-extrabold text-green-700">₹{order.total_price ?? 0}</span>
        </div>

        <div className="mt-3 text-center">
          <span className="inline-block text-[10px] font-bold px-3 py-1 rounded-full bg-green-100 text-green-800">{L('✓ PAID', 'చెల్లించారు')}</span>
        </div>

        <p className="text-[9px] text-gray-400 text-center mt-3 break-all">Ref: {paymentRef}</p>
        <p className="text-[10px] font-semibold text-green-700 text-center mt-2">{L('Thank you for supporting our farmers — GoGrameen Team 🌱', 'మా రైతులకు మద్దతు ఇచ్చినందుకు ధన్యవాదాలు — గోగ్రామీణ్ టీం')}</p>

